 62	    /**
 63	     * Increment the count for one class of animal.
 64	     * @param animalClass The class of animal to increment.
 65	     */
 66	    public void incrementCount(Class<?> animalClass)
 67	    {
 68	        Counter count = counters.get(animalClass);
 69	        if(count == null) {
 70	            // We do not have a counter for this species yet.
 71	            // Create one.
 72	            count = new Counter(animalClass.getName());
 73	            counters.put(animalClass, count);
 74	        }
 75	        count.increment();
 76	    }
