 86	    /**
 87	     * Determine whether the simulation is still viable.
 88	     * I.e., should it continue to run.
 89	     * @return true If there is more than one species alive.
 90	     */
 91	    public boolean isViable(Field field)
 92	    {
 93	        // How many counts are non-zero.
 94	        int nonZero = 0;
 95	        if(!countsValid) {
 96	            generateCounts(field);
 97	        }
 98	        for(Class<?> key : counters.keySet()) {
 99	            Counter info = counters.get(key);
100	            if(info.getCount() > 0) {
101	                nonZero++;
102	            }
103	        }
104	        return nonZero > 1;
105	    }
