107	    /**
108	     * Generate counts of the number of foxes and rabbits.
109	     * These are not kept up to date as foxes and rabbits
110	     * are placed in the field, but only when a request
111	     * is made for the information.
112	     * @param field The field to generate the stats for.
113	     */
114	    private void generateCounts(Field field)
115	    {
116	        reset();
117	        for(int row = 0; row < field.getDepth(); row++) {
118	            for(int col = 0; col < field.getWidth(); col++) {
119	                Object animal = field.getObjectAt(row, col);
120	                Plant plant = field.getPlantAt(row, col);
121	                if(animal != null) {
122	                    incrementCount(animal.getClass());
123	                }
124	                if(plant != null) {
125	                    incrementCount(plant.getClass());
126	                }
127	            }
128	        }
129	        countsValid = true;
130	    }
131	    public Map<Class<?>, Counter> getCounters()
132	    {
133	        return counters;
